INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('327a30c5-d1f8-51e8-9c52-37933ea0f774', 'Italy Project CSR-SC The Italian contribution to the CSR', 'Project CSR-SC The Italian contribution to the CSR dissemination campaign in Europe', 'With this document, which is presented on the occasion of the Venice Conference, the Ministry of Labor and Social Policies wants to make its own contribution to the debate European focus now on achieving a common reference framework on CSR. In particular, the work proposal of the Italian government for the development of culture, of CSR practices and tools is intended to be a starting point to start a new discussion extended to all interested stakeholders at national level and European level.', 'With this document, which is presented on the occasion of the Venice Conference, the Ministry of Labor and Social Policies wants to make its own contribution to the debate European focus now on achieving a common reference framework on CSR. In particular, the work proposal of the Italian government for the development of culture, of CSR practices and tools is intended to be a starting point to start a new discussion extended to all interested stakeholders at national level and European level.', 'With this document, which is presented on the occasion of the Venice Conference, the Ministry of Labor and Social Policies wants to make its own contribution to the debate European focus now on achieving a common reference framework on CSR. In particular, the work proposal of the Italian government for the development of culture, of CSR practices and tools is intended to be a starting point to start a new discussion extended to all interested stakeholders at national level and European level.', 'Italy', 'social', 'in_force', '2002-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_7', ARRAY['sdg8', 'other sustainability policy', 'italy', 'regulations', 'mandatory', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a2d6a97a-c0fd-5ee9-ae68-bc465c42fc05', 'Italy Report & Code of Conduct (The Preda Code)', 'Report & Code of Conduct (The Preda Code) 1999', 'This Code is proposed as a model aligned with the principles of international best practice, suitably adapted to take account of the specific features found in Italy, in the belief that its wholehearted adoption by listed companies will increase their reliability in the eyes of investors.', 'This Code is proposed as a model aligned with the principles of international best practice, suitably adapted to take account of the specific features found in Italy, in the belief that its wholehearted adoption by listed companies will increase their reliability in the eyes of investors.', 'This Code is proposed as a model aligned with the principles of international best practice, suitably adapted to take account of the specific features found in Italy, in the belief that its wholehearted adoption by listed companies will increase their reliability in the eyes of investors.', 'Italy', 'climate', 'in_force', '1999-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_24', ARRAY['italy', 'guidance_frameworks', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cbde49ac-f0b3-5021-b503-5375fefb4232', 'Italy Consolidated Law on Finance Legislative Decree 24 February', 'Consolidated Law on Finance Legislative Decree 24 February 1998, n. 58', 'The Consolidated Law on Finance, in effect from September 15, 2020, encompasses provisions on financial intermediation in Italy. This law, originating from Legislative Decree 24 February 1998, n. 58, was updated with changes from Legislative Decrees no. 84 of 14.7.2020 and no. 76 of 16.7.2020. The law is aimed at regulating financial activities, ensuring compliance with standards, and protecting consumers. It covers various aspects of financial operations and is essential for entities involved in financial intermediation.', 'The Consolidated Law on Finance, in effect from September 15, 2020, encompasses provisions on financial intermediation in Italy. This law, originating from Legislative Decree 24 February 1998, n. 58, was updated with changes from Legislative Decrees no. 84 of 14.7.2020 and no. 76 of 16.7.2020. The law is aimed at regulating financial activities, ensuring compliance with standards, and protecting consumers. It covers various aspects of financial operations and is essential for entities involved in financial intermediation.', 'The Consolidated Law on Finance, in effect from September 15, 2020, encompasses provisions on financial intermediation in Italy. This law, originating from Legislative Decree 24 February 1998, n. 58, was updated with changes from Legislative Decrees no. 84 of 14.7.2020 and no. 76 of 16.7.2020. The law is aimed at regulating financial activities, ensuring compliance with standards, and protecting consumers. It covers various aspects of financial operations and is essential for entities involved in financial intermediation.', 'Italy', 'governance', 'in_force', '1998-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_12', ARRAY['italy', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a08ddf1-fb68-54a9-8918-e6704e11c22f', 'Italy Legislative Decree 58 of 24 Feburary 1998 Consolidated', 'Legislative Decree 58 of 24 Feburary 1998 Consolidated law on financial intermediation pursuant to Articles 8 and 21 of Law 52 of 6 February 1996', 'This document is concerned with the legislative Decree 58 of 24 Feburary 1998 which consolidates the law on financial intermediation pursuant to Articles 8 and 21 of Law 52 of 6 February 1996.', 'This document is concerned with the legislative Decree 58 of 24 Feburary 1998 which consolidates the law on financial intermediation pursuant to Articles 8 and 21 of Law 52 of 6 February 1996.', 'This document is concerned with the legislative Decree 58 of 24 Feburary 1998 which consolidates the law on financial intermediation pursuant to Articles 8 and 21 of Law 52 of 6 February 1996.', 'Italy', 'climate', 'in_force', '1998-01-01'::date, 'Italy', 'https://www.carrotsandsticks.org/policies/85_25', ARRAY['disclosure', 'mandatory', 'italy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('acbb9250-83ca-5f7b-b475-f7a43832f74d', 'Ivory Coast Decree of November 30, 2012 Setting the', 'Decree No. 2012-1123 of November 30, 2012 Setting the Terms of Application of Ordinance No. 2012-487 of June 07, 2012 on the Investment Code', 'This decree sets out the guidelines for the implementation of the Investment Code, which was passed in 2012. The decree establishes procedures and requirements for foreign investors seeking to invest in Ivory Coast. It provides for the creation of a one-stop-shop for investment, which is responsible for facilitating the registration of new businesses and providing investors with the necessary permits and licenses. The decree also outlines the incentives available to investors, including tax exemptions, customs duty exemptions, and reduced rates on land leasehold. It further specifies the conditions for receiving these incentives, such as investing in priority sectors or making investments that create jobs. Furthermore, the decree establishes the Investment Promotion Council, which is responsible for promoting investment in Ivory Coast and coordinating investment-related activities between various government agencies and private sector entities. The decree does not explicitly require companies to disclose or report on their social or environmental impact. However, the Investment Code, which the decree sets out the guidelines for, does include provisions on corporate social responsibility (CSR). It encourages investors to adopt responsible business practices, such as protecting the environment, respecting human rights, and promoting sustainable development.', 'This decree sets out the guidelines for the implementation of the Investment Code, which was passed in 2012. The decree establishes procedures and requirements for foreign investors seeking to invest in Ivory Coast. It provides for the creation of a one-stop-shop for investment, which is responsible for facilitating the registration of new businesses and providing investors with the necessary permits and licenses. The decree also outlines the incentives available to investors, including tax exemptions, customs duty exemptions, and reduced rates on land leasehold. It further specifies the conditions for receiving these incentives, such as investing in priority sectors or making investments that create jobs. Furthermore, the decree establishes the Investment Promotion Council, which is responsible for promoting investment in Ivory Coast and coordinating investment-related activities between various government agencies and private sector entities. The decree does not explicitly require companies to disclose or report on their social or environmental impact. However, the Investment Code, which the decree sets out the guidelines for, does include provisions on corporate social responsibility (CSR). It encourages investors to adopt responsible business practices, such as protecting the environment, respecting human rights, and promoting sustainable development.', 'This decree sets out the guidelines for the implementation of the Investment Code, which was passed in 2012. The decree establishes procedures and requirements for foreign investors seeking to invest in Ivory Coast. It provides for the creation of a one-stop-shop for investment, which is responsible for facilitating the registration of new businesses and providing investors with the necessary permits and licenses. The decree also outlines the incentives available to investors, including tax exemptions, customs duty exemptions, and reduced rates on land leasehold. It further specifies the conditions for receiving these incentives, such as investing in priority sectors or making investments that create jobs. Furthermore, the decree establishes the Investment Promotion Council, which is responsible for promoting investment in Ivory Coast and coordinating investment-related activities between various government agencies and private sector entities. The decree does not explicitly require companies to disclose or report on their social or environmental impact. However, the Investment Code, which the decree sets out the guidelines for, does include provisions on corporate social responsibility (CSR). It encourages investors to adopt responsible business practices, such as protecting the environment, respecting human rights, and promoting sustainable development.', 'Ivory Coast', 'nature', 'in_force', '2012-01-01'::date, 'Ivory Coast', 'https://www.carrotsandsticks.org/policies/195_1', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg9', 'mandatory', 'ivory coast', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('81581be9-f67d-5189-93eb-5dbb547851c0', 'Jamaica PSOJ Corporate Governance Code For Micro, Small or', 'PSOJ Corporate Governance Code For Micro, Small or Medium-Sized Enterprises 2016', 'The Private Sector Organisation of Jamaica established the Corporate Governance Committee with a mission to become the key influencer in the delivery and adoption of corporate governance best business practices by providing access to knowledge and learning resources for our members and leaders of business enterprises so they can effectively compete in the global market.', 'The Private Sector Organisation of Jamaica established the Corporate Governance Committee with a mission to become the key influencer in the delivery and adoption of corporate governance best business practices by providing access to knowledge and learning resources for our members and leaders of business enterprises so they can effectively compete in the global market.', 'The Private Sector Organisation of Jamaica established the Corporate Governance Committee with a mission to become the key influencer in the delivery and adoption of corporate governance best business practices by providing access to knowledge and learning resources for our members and leaders of business enterprises so they can effectively compete in the global market.', 'Jamaica', 'governance', 'in_force', '2016-01-01'::date, 'Jamaica', 'https://www.carrotsandsticks.org/policies/86_5', ARRAY['sdg4', 'regulations', 'mandatory', 'jamaica', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79cdfe44-769c-5946-8e11-2077770a7681', 'Jamaica Code of Corporate Governance (2nd Edition) Volume 1', 'Code of Corporate Governance (2nd Edition) Volume 1 2009', 'The Code is intended to guide companies in implementing good practices in corporate governance in Jamaica.', 'The Code is intended to guide companies in implementing good practices in corporate governance in Jamaica.', 'The Code is intended to guide companies in implementing good practices in corporate governance in Jamaica.', 'Jamaica', 'governance', 'in_force', '2009-01-01'::date, 'Jamaica', 'https://www.carrotsandsticks.org/policies/86_4', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'jamaica', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c73df56-c0e7-504f-ae30-0d3a0fc8306f', 'Private Sector Organisation of Jamaica Proposed Code', 'Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2006', 'The Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2006 is based on the UK''s Combined Code on Corporate Governance. It outlines core Principles and Best Practices for publicly listed companies in Jamaica and non-listed companies in financial services. The code emphasizes the importance of effective Boards, transparent remuneration policies, shareholder dialogue, financial reporting, internal control, and audit oversight. It encourages companies to either comply with the Principles or provide a reasoned explanation for non-compliance. The code aims to enhance corporate governance practices in Jamaica and align with international standards.', 'The Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2006 is based on the UK''s Combined Code on Corporate Governance. It outlines core Principles and Best Practices for publicly listed companies in Jamaica and non-listed companies in financial services. The code emphasizes the importance of effective Boards, transparent remuneration policies, shareholder dialogue, financial reporting, internal control, and audit oversight. It encourages companies to either comply with the Principles or provide a reasoned explanation for non-compliance. The code aims to enhance corporate governance practices in Jamaica and align with international standards.', 'The Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2006 is based on the UK''s Combined Code on Corporate Governance. It outlines core Principles and Best Practices for publicly listed companies in Jamaica and non-listed companies in financial services. The code emphasizes the importance of effective Boards, transparent remuneration policies, shareholder dialogue, financial reporting, internal control, and audit oversight. It encourages companies to either comply with the Principles or provide a reasoned explanation for non-compliance. The code aims to enhance corporate governance practices in Jamaica and align with international standards.', 'Jamaica', 'climate', 'in_force', '2006-01-01'::date, 'Jamaica', 'https://www.carrotsandsticks.org/policies/86_3', ARRAY['regulations', 'mandatory', 'jamaica', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4adeee25-bfd4-5b00-bf0a-829c7904bf5f', 'Private Sector Organisation of Jamaica Proposed Code', 'Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2005', 'The Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2005 is a disclosure policy based on the UK''s Combined Code on Corporate Governance. It aims to enhance corporate governance practices in Jamaica by setting out core principles and best practices for publicly listed companies and those in financial services. The Code emphasizes the importance of board effectiveness, independence, transparent remuneration policies, shareholder dialogue, financial reporting, internal control, and engagement with institutional investors. The comply or explain approach allows companies flexibility in governance policies while promoting accountability and transparency. The policy is recommended for adoption starting January 1, 2007.', 'The Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2005 is a disclosure policy based on the UK''s Combined Code on Corporate Governance. It aims to enhance corporate governance practices in Jamaica by setting out core principles and best practices for publicly listed companies and those in financial services. The Code emphasizes the importance of board effectiveness, independence, transparent remuneration policies, shareholder dialogue, financial reporting, internal control, and engagement with institutional investors. The comply or explain approach allows companies flexibility in governance policies while promoting accountability and transparency. The policy is recommended for adoption starting January 1, 2007.', 'The Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2005 is a disclosure policy based on the UK''s Combined Code on Corporate Governance. It aims to enhance corporate governance practices in Jamaica by setting out core principles and best practices for publicly listed companies and those in financial services. The Code emphasizes the importance of board effectiveness, independence, transparent remuneration policies, shareholder dialogue, financial reporting, internal control, and engagement with institutional investors. The comply or explain approach allows companies flexibility in governance policies while promoting accountability and transparency. The policy is recommended for adoption starting January 1, 2007.', 'Jamaica', 'climate', 'in_force', '2005-01-01'::date, 'Jamaica', 'https://www.carrotsandsticks.org/policies/86_2', ARRAY['regulations', 'mandatory', 'jamaica', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0018d0c0-4c26-518d-8b65-29b6e763e7cc', 'Private Sector Organisation of Jamaica Proposed Code', 'Private Sector Organisation of Jamaica Proposed Code on Corporate Governance 2003', 'The proposed Code, which is based on The Combined Code on Corporate Governance issued by the Financial Reporting Council (FRC) of the United Kingdom (UK) on 23 July 2003, has been compiled by the Corporate Governance Committee of the Private Sector Organisation of Jamaica. It is proposed that this Code should become effective for annual reporting periods commencing on or after 1st January 2007. It is hoped that those companies that are able to do so will adhere to the principles of the Code as early as possible. The Code sets out the core principles and Code of Best Practice that the Committee proposes for adoption by
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e75f9118-e731-560a-a28b-e9d6af9f5df9', 'Japan Preparing Securities Reports (Sustainability-Related Financial Disclosures) (For submission', 'Guidelines for Preparing Securities Reports (Sustainability-Related Financial Disclosures) (For submission in the fiscal year ending March 2025)', 'Japan''s "Guidelines for Preparing Securities Reports (Sustainability-Related Financial Disclosures)" outlines requirements for fiscal year ending March 2025 submissions. The policy aims to guide corporations in disclosing sustainability-related financial information following specific criteria developed by the Sustainability Standards Board of Japan. Targeted at entities preparing securities reports and focusing on sustainability disclosures.', 'Japan''s "Guidelines for Preparing Securities Reports (Sustainability-Related Financial Disclosures)" outlines requirements for fiscal year ending March 2025 submissions. The policy aims to guide corporations in disclosing sustainability-related financial information following specific criteria developed by the Sustainability Standards Board of Japan. Targeted at entities preparing securities reports and focusing on sustainability disclosures.', 'Japan''s "Guidelines for Preparing Securities Reports (Sustainability-Related Financial Disclosures)" outlines requirements for fiscal year ending March 2025 submissions. The policy aims to guide corporations in disclosing sustainability-related financial information following specific criteria developed by the Sustainability Standards Board of Japan. Targeted at entities preparing securities reports and focusing on sustainability disclosures.', 'Japan', 'climate', 'in_force', '2025-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_58', ARRAY['guidance_frameworks', 'sdg13', 'sdg16', 'sdg12', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('000e34f0-756f-54c9-8e07-083687b1afa1', 'Japan Respect for Human Rights in Responsible Supply Chains', 'Guidelines on Respect for Human Rights in Responsible Supply Chains', 'The Guidelines for Respecting Human Rights in Supply Chains were established by the Japanese Ministry of Economy, Trade and Industry (METI) in March 2022, based on international standards such as the UN Guiding Principles, the OECD Guidelines for Multinational Enterprises, and the ILO MNE Declaration. The purpose is to promote corporate efforts to respect human rights by explaining the activities that business enterprises should undertake in a concrete and easy-to-understand manner. The Guidelines will be reviewed to reflect subsequent developments of international standards, and METI will create additional materials to support practitioners in implementing the Guidelines. The establishment of the Guidelines was a response to the strong demand from stakeholders for the Japanese government to take initiatives to promote business efforts that respect human rights.', 'The Guidelines for Respecting Human Rights in Supply Chains were established by the Japanese Ministry of Economy, Trade and Industry (METI) in March 2022, based on international standards such as the UN Guiding Principles, the OECD Guidelines for Multinational Enterprises, and the ILO MNE Declaration. The purpose is to promote corporate efforts to respect human rights by explaining the activities that business enterprises should undertake in a concrete and easy-to-understand manner. The Guidelines will be reviewed to reflect subsequent developments of international standards, and METI will create additional materials to support practitioners in implementing the Guidelines. The establishment of the Guidelines was a response to the strong demand from stakeholders for the Japanese government to take initiatives to promote business efforts that respect human rights.', 'The Guidelines for Respecting Human Rights in Supply Chains were established by the Japanese Ministry of Economy, Trade and Industry (METI) in March 2022, based on international standards such as the UN Guiding Principles, the OECD Guidelines for Multinational Enterprises, and the ILO MNE Declaration. The purpose is to promote corporate efforts to respect human rights by explaining the activities that business enterprises should undertake in a concrete and easy-to-understand manner. The Guidelines will be reviewed to reflect subsequent developments of international standards, and METI will create additional materials to support practitioners in implementing the Guidelines. The establishment of the Guidelines was a response to the strong demand from stakeholders for the Japanese government to take initiatives to promote business efforts that respect human rights.', 'Japan', 'climate', 'in_force', '2022-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_56', ARRAY['guidance_frameworks', 'sdg16', 'japan', 'sdg12', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3bc6d747-1443-5ff2-96f8-841148561b4e', 'Japan’s Corporate Governance Code (TSE)', 'Japan’s Corporate Governance Code (TSE)', 'Japan’s Corporate Governance Code, revised in 2021 and issued by the Tokyo Stock Exchange, establishes principles to enhance corporate governance among listed companies in Japan. The Code aims to promote transparent, fair, timely, and decisive decision-making, balancing the interests of shareholders and stakeholders. It fosters sustainable growth and increased corporate value over the mid- to long-term by encouraging companies to adopt effective governance practices voluntarily.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('888acb2f-2a50-560a-8101-5dd38275e908', 'Japan’s Corporate Governance Code', 'Japan’s Corporate Governance Code 2021', 'This is the 2021 version of Japan''s Corporate Governance Code seeking sustainable corporate growth and increased corporate value over the mid-to long-term.', 'This is the 2021 version of Japan''s Corporate Governance Code seeking sustainable corporate growth and increased corporate value over the mid-to long-term.', 'This is the 2021 version of Japan''s Corporate Governance Code seeking sustainable corporate growth and increased corporate value over the mid-to long-term.', 'Japan', 'climate', 'in_force', '2021-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_53', ARRAY['other sustainability policy', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'japan', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('825b0128-4891-5463-ac1a-4477a5ef8828', 'Japan Local Biodiversity Strategies and Action Plans (LBSAPs)', 'Local Biodiversity Strategies and Action Plans (LBSAPs) to accelerate actions for biodiversity by local governments', 'This Policy Brief sets out policy recommendations to encourage more municipalities to develop LBSAPs and to help them improve their LBSAPs for better outcomes. It presents these results from PANCES broadly and concisely.', 'This Policy Brief sets out policy recommendations to encourage more municipalities to develop LBSAPs and to help them improve their LBSAPs for better outcomes. It presents these results from PANCES broadly and concisely.', 'This Policy Brief sets out policy recommendations to encourage more municipalities to develop LBSAPs and to help them improve their LBSAPs for better outcomes. It presents these results from PANCES broadly and concisely.', 'Japan', 'climate', 'in_force', '2021-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_54', ARRAY['sdg4', 'sdg2', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'japan', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8d57510b-d931-5c81-b1d3-df52097a7e55', 'Japan Basic Guidelines on Climate Transition Finance', 'Basic Guidelines on Climate Transition Finance, 2021', 'The purpose of these Guidelines is to strengthen the position of climate transition finance as a means of financing transitions, especially in hard-to-abate sectors, and introduce more funds in order to contribute to achieving the 2050 carbon-neutral goals and the Paris Agreement, by popularizing transition finance, which is in its startup phase, and ensuring the credibility of financing in labeling as transition finance.', 'The purpose of these Guidelines is to strengthen the position of climate transition finance as a means of financing transitions, especially in hard-to-abate sectors, and introduce more funds in order to contribute to achieving the 2050 carbon-neutral goals and the Paris Agreement, by popularizing transition finance, which is in its startup phase, and ensuring the credibility of financing in labeling as transition finance.', 'The purpose of these Guidelines is to strengthen the position of climate transition finance as a means of financing transitions, especially in hard-to-abate sectors, and introduce more funds in order to contribute to achieving the 2050 carbon-neutral goals and the Paris Agreement, by popularizing transition finance, which is in its startup phase, and ensuring the credibility of financing in labeling as transition finance.', 'Japan', 'climate', 'in_force', '2021-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_57', ARRAY['guidance_frameworks', 'sdg13', 'sdg7', 'japan', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('402f3f11-dc8c-5f53-b15b-364934ef1198', 'Japan Practical Handbook for ESG Disclosure', 'Practical Handbook for ESG Disclosure', 'The Handbook aims to help listed companies which choose to link ESG issues to corporate value and disclose about those issues in a way that the links can be clearly understood. For that reason, rather than listing specific data points to disclose, it focuses on issues that listed companies come across when looking at ESG disclosure internally.', 'The Handbook aims to help listed companies which choose to link ESG issues to corporate value and disclose about those issues in a way that the links can be clearly understood. For that reason, rather than listing specific data points to disclose, it focuses on issues that listed companies come across when looking at ESG disclosure internally.', 'The Handbook aims to help listed companies which choose to link ESG issues to corporate value and disclose about those issues in a way that the links can be clearly understood. For that reason, rather than listing specific data points to disclose, it focuses on issues that listed companies come across when looking at ESG disclosure internally.', 'Japan', 'climate', 'in_force', '2020-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_15', ARRAY['regulations', 'sdg7', 'mandatory', 'japan', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('072e8fa9-c2e8-55fe-8b0d-43e9b07e5b34', 'Japan Model Guidance for Companies on Reporting on ESG', 'Model Guidance for Companies on Reporting on ESG Information', 'This document allows companies to disclose ESG information to investors in an effective and reliable manner. In order to do so, it provides guidance to guide companies in advancing reporting on ESG information, as well as suggestions on the benefits that companies can gain from making such reports.', 'This document allows companies to disclose ESG information to investors in an effective and reliable manner. In order to do so, it provides guidance to guide companies in advancing reporting on ESG information, as well as suggestions on the benefits that companies can gain from making such reports.', 'This document allows companies to disclose ESG information to investors in an effective and reliable manner. In order to do so, it provides guidance to guide companies in advancing reporting on ESG information, as well as suggestions on the benefits that companies can gain from making such reports.', 'Japan', 'climate', 'in_force', '2019-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_12', ARRAY['guidance_frameworks', 'sdg7', 'mandatory', 'japan', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0ea38424-0b66-5c68-a709-b3811982a349', 'Japan''s Corporate Governance Code: Seeking Sustainable Corporate Growth', 'Japan''s Corporate Governance Code: Seeking Sustainable Corporate Growth and Increased Corporate Value over the Mid-to Long-Term', 'This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan. It is expected that the Code''s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies'' self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid-to long-term.', 'This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan. It is expected that the Code''s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies'' self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid-to long-term.', 'This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan. It is expected that the Code''s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies'' self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid-to long-term.', 'Japan', 'climate', 'in_force', '2018-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_11', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'japan', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('02586ef8-4c46-52c5-a230-8bb466614b6d', 'Japan Outline of the “Act on the Arrangement', 'Outline of the “Act on the Arrangement of Related Acts to Promote Work Style Reform” (Act No. 71 of 2018)', 'This act is concerned with promoting work style reform comprehensively and creating a society that allows people to choose a preferred work style that suits their circumstances. The government takes measures to help end the practice of long working hours, allow for flexible and diverse work styles and ensure that all workers receive fair treatment , etc.', 'This act is concerned with promoting work style reform comprehensively and creating a society that allows people to choose a preferred work style that suits their circumstances. The government takes measures to help end the practice of long working hours, allow for flexible and diverse work styles and ensure that all workers receive fair treatment , etc.', 'This act is concerned with promoting work style reform comprehensively and creating a society that allows people to choose a preferred work style that suits their circumstances. The government takes measures to help end the practice of long working hours, allow for flexible and diverse work styles and ensure that all workers receive fair treatment , etc.', 'Japan', 'social', 'in_force', '2018-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_23', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'japan', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1afe3d7b-08f5-5ef9-a0ff-0918c4cb90d7', 'Japan Investor and Company Engagement', 'Guidelines for Investor and Company Engagement 2018', 'The Guidelines herein provide agenda items for engagement that institutional investors and companies are expected to focus on based on the Stewardship Code and the Corporate Governance Code, in recognition of the corporate governance issues prevalent at this time.', 'The Guidelines herein provide agenda items for engagement that institutional investors and companies are expected to focus on based on the Stewardship Code and the Corporate Governance Code, in recognition of the corporate governance issues prevalent at this time.', 'The Guidelines herein provide agenda items for engagement that institutional investors and companies are expected to focus on based on the Stewardship Code and the Corporate Governance Code, in recognition of the corporate governance issues prevalent at this time.', 'Japan', 'nature', 'in_force', '2018-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_28', ARRAY['guidance_frameworks', 'sdg14', 'other sustainability policy', 'sdg16', 'japan', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('88f7faec-4a6d-58c3-a6c7-dfbb287f8b88', 'Japan Points to Note Regarding Disclosure of Corporate Affairs', 'Points to Note Regarding Disclosure of Corporate Affairs', 'This Guideline merely indicates the points to note (the standards for interpretation and operation of laws and regulations that are considered to be optimal as of the time of their enactment or issuance) and the standards or guides for making examinations or dispositions, in applying laws and regulations. It does not preclude one from handling a matter differently from this Guideline within the scope of laws and regulations, according to the circumstances of individual cases.', 'This Guideline merely indicates the points to note (the standards for interpretation and operation of laws and regulations that are considered to be optimal as of the time of their enactment or issuance) and the standards or guides for making examinations or dispositions, in applying laws and regulations. It does not preclude one from handling a matter differently from this Guideline within the scope of laws and regulations, according to the circumstances of individual cases.', 'This Guideline merely indicates the points to note (the standards for interpretation and operation of laws and regulations that are considered to be optimal as of the time of their enactment or issuance) and the standards or guides for making examinations or dispositions, in applying laws and regulations. It does not preclude one from handling a matter differently from this Guideline within the scope of laws and regulations, according to the circumstances of individual cases.', 'Japan', 'governance', 'in_force', '2018-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_44', ARRAY['japan', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3694a650-e6c6-53a5-a15c-dd8b5ea656c5', 'Japan Environmental Reporting Guidance', 'Environmental Reporting Guidance', 'The guidelines aim to constitute a framework for international regulations, practical trends, and integrated environmental reporting. In order that these guidelines be easy to use by both advanced entities as well as mid-sized and smaller entities, the guidelines themselves are to be compact in structure and be supplemented by guidance and technical notes, containing processes for environmental report creation, explanations of difficult report items, and various examples.', 'The guidelines aim to constitute a framework for international regulations, practical trends, and integrated environmental reporting. In order that these guidelines be easy to use by both advanced entities as well as mid-sized and smaller entities, the guidelines themselves are to be compact in structure and be supplemented by guidance and technical notes, containing processes for environmental report creation, explanations of difficult report items, and various examples.', 'The guidelines aim to constitute a framework for international regulations, practical trends, and integrated environmental reporting. In order that these guidelines be easy to use by both advanced entities as well as mid-sized and smaller entities, the guidelines themselves are to be compact in structure and be supplemented by guidance and technical notes, containing processes for environmental report creation, explanations of difficult report items, and various examples.', 'Japan', 'climate', 'in_force', '2018-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_9', ARRAY['guidance_frameworks', 'sdg7', 'mandatory', 'japan', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed5aa010-41d2-527b-9cf7-ed0f6b8f27b5', 'Japan ESG Working Group Report', 'ESG Working Group Report 2017', 'The “Working Group on Incorporating Issues Regarding Sustainability into Investment” (ESG Working Group) has produced the attached Guidebook aiming to improve fundamental understanding of ESG investment, with a particular focus on “E”.', 'The “Working Group on Incorporating Issues Regarding Sustainability into Investment” (ESG Working Group) has produced the attached Guidebook aiming to improve fundamental understanding of ESG investment, with a particular focus on “E”.', 'The “Working Group on Incorporating Issues Regarding Sustainability into Investment” (ESG Working Group) has produced the attached Guidebook aiming to improve fundamental understanding of ESG investment, with a particular focus on “E”.', 'Japan', 'climate', 'in_force', '2017-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_1', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'japan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f30fb21a-f350-534c-af8d-ae22f460d98d', 'Principles for Responsible Institutional Investors (Japan''s Stewardship Code)', 'Principles for Responsible Institutional Investors (Japan''s Stewardship Code) 2017', 'This is the revised 2017 version of the Japan Stewardship Code which defines principles considered to be helpful for institutional investors who behave as responsible institutional investors in fulfilling their stewardship responsibilities with due regard both to their clients and beneficiaries and to investee companies.', 'This is the revised 2017 version of the Japan Stewardship Code which defines principles considered to be helpful for institutional investors who behave as responsible institutional investors in fulfilling their stewardship responsibilities with due regard both to their clients and beneficiaries and to investee companies.', 'This is the revised 2017 version of the Japan Stewardship Code which defines principles considered to be helpful for institutional investors who behave as responsible institutional investors in fulfilling their stewardship responsibilities with due regard both to their clients and beneficiaries and to investee companies.', 'Japan', 'governance', 'in_force', '2017-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_19', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('80647dd2-5251-50e0-a3df-8d859e2e9089', 'Japan Green Bond Guidelines', 'Green Bond Guidelines 2017', 'These Guidelines aim to raise the visibility of Green Bonds and expand Green Bond issuance and investment within Japan in line with the global development of the Green Bond market.', 'These Guidelines aim to raise the visibility of Green Bonds and expand Green Bond issuance and investment within Japan in line with the global development of the Green Bond market.', 'These Guidelines aim to raise the visibility of Green Bonds and expand Green Bond issuance and investment within Japan in line with the global development of the Green Bond market.', 'Japan', 'climate', 'in_force', '2017-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_25', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg9', 'sdg7', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf368b3f-2054-5f5b-aa6e-81f6305f57dc', 'Japan Integrated Corporate Disclosure and Company-Investor Dialogues for Collaborative', 'Guidance for Integrated Corporate Disclosure and Company-Investor Dialogues for Collaborative Value Creation', 'This Guidance is intended to deepen mutual understanding between companies and investors through information disclosure and dialogue/engagement and promote collaborative activities to create sustainable value.', 'This Guidance is intended to deepen mutual understanding between companies and investors through information disclosure and dialogue/engagement and promote collaborative activities to create sustainable value.', 'This Guidance is intended to deepen mutual understanding between companies and investors through information disclosure and dialogue/engagement and promote collaborative activities to create sustainable value.', 'Japan', 'climate', 'in_force', '2017-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_26', ARRAY['guidance_frameworks', 'sdg7', 'mandatory', 'japan', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c21d383a-ff1e-5983-b93d-65d503e413ef', 'Japan EcoAction 21 Guidelines', 'EcoAction 21 Guidelines', 'The 2017 version of the EcoAction 21 Guidelines, maintains the traditional aspects of an EMS, however includes additional key elements to assist organizations with greater environmental management.', 'The 2017 version of the EcoAction 21 Guidelines, maintains the traditional aspects of an EMS, however includes additional key elements to assist organizations with greater environmental management.', 'The 2017 version of the EcoAction 21 Guidelines, maintains the traditional aspects of an EMS, however includes additional key elements to assist organizations with greater environmental management.', 'Japan', 'circularity', 'in_force', '2017-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_37', ARRAY['other sustainability policy', 'regulations', 'sdg12', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c62db8fb-7b6e-5170-abc9-e0e8a30e6071', 'Japan Charter of Corporate Behaviour', 'The Charter of Corporate Behaviour', 'Keidanren will revise its Charter of Corporate Behavior with the primary aim of proactively delivering on the SDGs through the realization of Society 5.0. Member corporations should fully recognize that their development is founded on the realization of a sustainable society, and they should exercise their social responsibilities by creating new added value and generating employment that will be beneficial to society at large and by conducting their business in a manner that takes the environment, society, and governance (ESG) into consideration. Corporations should also encourage behavioral changes not only within their own corporations, but also in their group companies and supply chains, and, by fostering partnership and collaboration with a diverse range of organizations, act toward the realization of Society 5.0 and through that, deliver on the SDGs.', 'Keidanren will revise its Charter of Corporate Behavior with the primary aim of proactively delivering on the SDGs through the realization of Society 5.0. Member corporations should fully recognize that their development is founded on the realization of a sustainable society, and they should exercise their social responsibilities by creating new added value and generating employment that will be beneficial to society at large and by conducting their business in a manner that takes the environment, society, and governance (ESG) into consideration. Corporations should also encourage behavioral changes not only within their own corporations, but also in their group companies and supply chains, and, by fostering partnership and collaboration with a diverse range of organizations, act toward the realization of Society 5.0 and through that, deliver on the SDGs.', 'Keidanren will revise its Charter of Corporate Behavior with the primary aim of proactively delivering on the SDGs through the realization of Society 5.0. Member corporations should fully recognize that their development is founded on the realization of a sustainable society, and they should exercise their social responsibilities by creating new added value and generating employment that will be beneficial to society at large and by conducting their business in a manner that takes the environment, society, and governance (ESG) into consideration. Corporations should also encourage behavioral changes not only within their own corporations, but also in their group companies and supply chains, and, by fostering partnership and collaboration with a diverse range of organizations, act toward the realization of Society 5.0 and through that, deliver on the SDGs.', 'Japan', 'climate', 'in_force', '2017-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_50', ARRAY['sdg8', 'sdg2', 'other sustainability policy', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'japan', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
