INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ee1bc04b-4431-514e-85e5-2ae8554e9e2f', 'Japan''s Corporate Governance Code Seeking Sustainable Corporate Growth', 'Japan''s Corporate Governance Code Seeking Sustainable Corporate Growth and Increased Corporate Value over the Mid- to Long-Term 2015', 'In this Corporate Governance Code, “corporate governance” means a structure for transparent, fair, timely and decisive decision-making by companies, with due attention to the needs and perspectives of shareholders and also customers, employees and local communities. This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan.It is expected that the Code’s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies’ self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid- to long-term.', 'In this Corporate Governance Code, “corporate governance” means a structure for transparent, fair, timely and decisive decision-making by companies, with due attention to the needs and perspectives of shareholders and also customers, employees and local communities. This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan.It is expected that the Code’s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies’ self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid- to long-term.', 'In this Corporate Governance Code, “corporate governance” means a structure for transparent, fair, timely and decisive decision-making by companies, with due attention to the needs and perspectives of shareholders and also customers, employees and local communities. This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan.It is expected that the Code’s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies’ self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid- to long-term.', 'Japan', 'climate', 'in_force', '2015-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_18', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg16', 'japan', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
