INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9e7e1c9d-c935-525f-9d7c-99e491ba6403', 'Principles for Responsible Institutional Investors (Japan’s Stewardship Code)', 'Principles for Responsible Institutional Investors (Japan’s Stewardship Code)', 'Japan’s Stewardship Code, introduced in 2014, outlines principles for responsible institutional investors to promote sustainable corporate growth and long-term value creation. Developed by the Financial Services Agency’s Council of Experts, the Code emphasizes stewardship responsibilities, defined as enhancing medium- to long-term investment returns for clients and beneficiaries through purposeful dialogue and constructive engagement with investee companies. The Code complements corporate governance efforts by fostering collaboration between boards and institutional investors.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('681d517d-e509-5998-97af-b83feeddfc75', 'Japan''s Corporate Governance Code (Exposure Draft)', 'Japan''s Corporate Governance Code (Exposure Draft) 2014', 'This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan. It is expected that the Code’s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies’ self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid- to long-term.', 'This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan. It is expected that the Code’s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies’ self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid- to long-term.', 'This Corporate Governance Code establishes fundamental principles for effective corporate governance at listed companies in Japan. It is expected that the Code’s appropriate implementation will contribute to the development and success of companies, investors and the Japanese economy as a whole through individual companies’ self-motivated actions so as to achieve sustainable growth and increase corporate value over the mid- to long-term.', 'Japan', 'governance', 'in_force', '2014-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_17', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'japan']::text[]) ON CONFLICT (id) DO NOTHING;
