INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('787ccddb-dd9c-5510-af6c-38c2a3c59665', 'Japan Principles for financial action towards a sustainable society', 'Principles for financial action towards a sustainable society', 'This set of Principles was drawn up as guidelines for action by financial institutions concerned with the future of the planet and seeking to fulfil their roles and responsibilities in shaping a sustainable society. It is also intended as a starting point for like-minded financial institutions to cooperate without reference to their specific industry types, size and geography.', 'This set of Principles was drawn up as guidelines for action by financial institutions concerned with the future of the planet and seeking to fulfil their roles and responsibilities in shaping a sustainable society. It is also intended as a starting point for like-minded financial institutions to cooperate without reference to their specific industry types, size and geography.', 'This set of Principles was drawn up as guidelines for action by financial institutions concerned with the future of the planet and seeking to fulfil their roles and responsibilities in shaping a sustainable society. It is also intended as a starting point for like-minded financial institutions to cooperate without reference to their specific industry types, size and geography.', 'Japan', 'climate', 'in_force', '2012-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_6', ARRAY['other sustainability policy', 'sdg9', 'regulations', 'sdg11', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a5daae12-4ae7-5063-83bb-b219f7d64e9d', 'Japan Friendly Corporate Responsibility - ISO26000 and SME case', 'Friendly Corporate Responsibility - ISO26000 and SME case', 'An easy-to-understand explanation of the points of ISO 26000, the international standard for social responsibility, for companies. SMEs should understand ISO26000 and take social responsibility initiatives. It is intended to serve as a guide, considered to be a particularly useful reference when considering specific initiatives.', 'An easy-to-understand explanation of the points of ISO 26000, the international standard for social responsibility, for companies. SMEs should understand ISO26000 and take social responsibility initiatives. It is intended to serve as a guide, considered to be a particularly useful reference when considering specific initiatives.', 'An easy-to-understand explanation of the points of ISO 26000, the international standard for social responsibility, for companies. SMEs should understand ISO26000 and take social responsibility initiatives. It is intended to serve as a guide, considered to be a particularly useful reference when considering specific initiatives.', 'Japan', 'governance', 'in_force', '2010-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_36', ARRAY['japan', 'mandatory', 'other sustainability policy', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6a7a6093-7398-5937-8348-6e2d119a9745', 'Japan Greenhouse gas emission calculation / reporting / publication', 'Greenhouse gas emission calculation / reporting / publication system briefing session', 'The policy outlines Japan''s greenhouse gas emission calculation, reporting, and publication system introduced in 2006 to promote voluntary efforts by disclosing emissions data. It requires entities emitting above a certain threshold to report their emissions to the national government annually. The reported data is collected, published, and visualized to foster emission control understanding and efforts. The system utilizes the Energy Conservation Law framework for reporting energy origins and is mandatory for specified emitters. The information is aggregated and disclosed publicly by the government.', 'The policy outlines Japan''s greenhouse gas emission calculation, reporting, and publication system introduced in 2006 to promote voluntary efforts by disclosing emissions data. It requires entities emitting above a certain threshold to report their emissions to the national government annually. The reported data is collected, published, and visualized to foster emission control understanding and efforts. The system utilizes the Energy Conservation Law framework for reporting energy origins and is mandatory for specified emitters. The information is aggregated and disclosed publicly by the government.', 'The policy outlines Japan''s greenhouse gas emission calculation, reporting, and publication system introduced in 2006 to promote voluntary efforts by disclosing emissions data. It requires entities emitting above a certain threshold to report their emissions to the national government annually. The reported data is collected, published, and visualized to foster emission control understanding and efforts. The system utilizes the Energy Conservation Law framework for reporting energy origins and is mandatory for specified emitters. The information is aggregated and disclosed publicly by the government.', 'Japan', 'climate', 'in_force', '2006-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_29', ARRAY['sdg13', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'japan', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eec8e467-5512-5d5c-b48f-eb4395b5d6c6', 'Japan Outline of Amendments to the Securities and Exchange', 'Outline of Amendments to the Securities and Exchange Law and Other Related Laws', 'The Amendment to the Financial Instruments and Exchange Act (2006) is a cornerstone of Japan’s regulatory framework for financial markets. It introduces comprehensive measures to ensure market transparency, protect investors, and promote fair trading practices. The amendment addresses critical areas such as disclosure requirements, corporate governance, and risk management, aligning Japan’s financial regulations with global standards.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0766f236-0f87-5507-84cd-c20099ff80ec', 'Japan Civil Aeronautics Act', 'Civil Aeronautics Act', 'The purpose of this Act is to promote the development of civil and general aviation and to enhance public welfare by providing for the methods to ensure the safety of aircraft and to prevent problems arising from navigation of aircraft, and by ensuring transportation safety and improving convenience for users through proper and rational management of business for operating aircraft, in conformity with both the provisions of the Convention on International Civil Aviation as well as the standards, practices and procedures adopted as Annexes hereto.', 'The purpose of this Act is to promote the development of civil and general aviation and to enhance public welfare by providing for the methods to ensure the safety of aircraft and to prevent problems arising from navigation of aircraft, and by ensuring transportation safety and improving convenience for users through proper and rational management of business for operating aircraft, in conformity with both the provisions of the Convention on International Civil Aviation as well as the standards, practices and procedures adopted as Annexes hereto.', 'The purpose of this Act is to promote the development of civil and general aviation and to enhance public welfare by providing for the methods to ensure the safety of aircraft and to prevent problems arising from navigation of aircraft, and by ensuring transportation safety and improving convenience for users through proper and rational management of business for operating aircraft, in conformity with both the provisions of the Convention on International Civil Aviation as well as the standards, practices and procedures adopted as Annexes hereto.', 'Japan', 'climate', 'in_force', '2006-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_7', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'japan', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffd402b6-4469-5739-91a8-8497b53bebf1', 'Japan Environmental Accounting Guidelines', 'Environmental Accounting Guidelines 2005', 'The Guidelines are intended to insure that the information disclosed takes into consideration the needs of the various stakeholders.They also provide the concepts behind gaining a more detailed ascertainment where necessary of more precise information content, with consideration given to the usefulness of the application of these concepts within the companies and other organizations as well.', 'The Guidelines are intended to insure that the information disclosed takes into consideration the needs of the various stakeholders.They also provide the concepts behind gaining a more detailed ascertainment where necessary of more precise information content, with consideration given to the usefulness of the application of these concepts within the companies and other organizations as well.', 'The Guidelines are intended to insure that the information disclosed takes into consideration the needs of the various stakeholders.They also provide the concepts behind gaining a more detailed ascertainment where necessary of more precise information content, with consideration given to the usefulness of the application of these concepts within the companies and other organizations as well.', 'Japan', 'governance', 'in_force', '2005-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_38', ARRAY['japan', 'voluntary', 'guidance_frameworks', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7eab8a1f-4289-58f4-9d1f-95334a31fc93', 'Japan Principles of Corporate Governance for Listed Companies', 'Principles of Corporate Governance for Listed Companies 2004', 'These Principles of Corporate Governance have not been designed to stipulate a specific model policies or aggregations of policies on corporate governance as the best or minimum standards for corporate governance. Therefore, the purpose of these Principles is not to require listed companies to adopt minimum standard policies or models for corporate governance, nor to demand companies that do not adopt the best policies or models to explain why. The respective items in these Principles have been set forth pursuant to the structure of the OECD Principles.', 'These Principles of Corporate Governance have not been designed to stipulate a specific model policies or aggregations of policies on corporate governance as the best or minimum standards for corporate governance. Therefore, the purpose of these Principles is not to require listed companies to adopt minimum standard policies or models for corporate governance, nor to demand companies that do not adopt the best policies or models to explain why. The respective items in these Principles have been set forth pursuant to the structure of the OECD Principles.', 'These Principles of Corporate Governance have not been designed to stipulate a specific model policies or aggregations of policies on corporate governance as the best or minimum standards for corporate governance. Therefore, the purpose of these Principles is not to require listed companies to adopt minimum standard policies or models for corporate governance, nor to demand companies that do not adopt the best policies or models to explain why. The respective items in these Principles have been set forth pursuant to the structure of the OECD Principles.', 'Japan', 'climate', 'in_force', '2004-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_20', ARRAY['guidance_frameworks', 'sdg7', 'sdg16', 'japan', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a9819837-8477-5aa7-a264-86c1e16ee429', 'Japan Promotion of Business Activities with Environmental Consideration', 'Law Concerning the Promotion of Business Activities with Environmental Consideration', 'The purpose of this law is to clarify the responsibilities of the State in providing and making use of information on the state of business-related environmental consideration and to take measures to prepare and publish environmental reports by Specified Corporations so as to ensure appropriate business-related environmental conservation, thereby contributing to ensuring a healthy and cultured living for both the present and future generations of the nation.', 'The purpose of this law is to clarify the responsibilities of the State in providing and making use of information on the state of business-related environmental consideration and to take measures to prepare and publish environmental reports by Specified Corporations so as to ensure appropriate business-related environmental conservation, thereby contributing to ensuring a healthy and cultured living for both the present and future generations of the nation.', 'The purpose of this law is to clarify the responsibilities of the State in providing and making use of information on the state of business-related environmental consideration and to take measures to prepare and publish environmental reports by Specified Corporations so as to ensure appropriate business-related environmental conservation, thereby contributing to ensuring a healthy and cultured living for both the present and future generations of the nation.', 'Japan', 'climate', 'in_force', '2004-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_5', ARRAY['other sustainability policy', 'sdg9', 'regulations', 'mandatory', 'japan', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('26eb156c-5af7-5560-ab2e-951b99a1ef00', 'Japan End-of-Life Vehicles (ELV) Recycling Law', 'End-of-Life Vehicles (ELV) Recycling Law', 'The purpose of the Law on Recycling of End-of-Life Vehicles (ELV Recycling Law), which defines role sharing among and responsibilities of automobile-related businesses, is to construct a new recycling system, prevent illegal dumping, reduce final disposal, and make full use of recyclable resources and reusable parts. The Law was promulgated on July 12, 2002, with its gradual enforcement beginning in January 2003. The Law was fully put into force in January 2005.', 'The purpose of the Law on Recycling of End-of-Life Vehicles (ELV Recycling Law), which defines role sharing among and responsibilities of automobile-related businesses, is to construct a new recycling system, prevent illegal dumping, reduce final disposal, and make full use of recyclable resources and reusable parts. The Law was promulgated on July 12, 2002, with its gradual enforcement beginning in January 2003. The Law was fully put into force in January 2005.', 'The purpose of the Law on Recycling of End-of-Life Vehicles (ELV Recycling Law), which defines role sharing among and responsibilities of automobile-related businesses, is to construct a new recycling system, prevent illegal dumping, reduce final disposal, and make full use of recyclable resources and reusable parts. The Law was promulgated on July 12, 2002, with its gradual enforcement beginning in January 2003. The Law was fully put into force in January 2005.', 'Japan', 'climate', 'in_force', '2002-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_4', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'japan', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6b712e14-85d7-5b2d-83fa-a7cd7f5bf39e', 'Japan Waste Management and Public Cleansing Law', 'Waste Management and Public Cleansing Law', 'This law is enacted for the purpose of preserving the living environment and improving public health through the restriction of waste discharge, appropriate sorting, storage, collection, transport, recycling, disposal, or the like of waste and conservation of a clean living environment.', 'This law is enacted for the purpose of preserving the living environment and improving public health through the restriction of waste discharge, appropriate sorting, storage, collection, transport, recycling, disposal, or the like of waste and conservation of a clean living environment.', 'This law is enacted for the purpose of preserving the living environment and improving public health through the restriction of waste discharge, appropriate sorting, storage, collection, transport, recycling, disposal, or the like of waste and conservation of a clean living environment.', 'Japan', 'climate', 'in_force', '2001-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_2', ARRAY['regulations', 'sdg11', 'mandatory', 'sdg12', 'disclosure', 'japan', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6ef67dee-d883-5992-9852-96c305dc56d7', 'Japan Revised Corporate Governance Principles', 'Revised Corporate Governance Principles 2001', 'The Committee revised the first version of the Principles by synthesizing these discussions, including the appointment of outside directors who are professors at national universities and certain revisions to the Commercial Code. These new Principles are part of a forward-thinking movement to improve Japanese corporate policy and are the result of earnest and vigorous debate between the practical and academic sides of this topic.', 'The Committee revised the first version of the Principles by synthesizing these discussions, including the appointment of outside directors who are professors at national universities and certain revisions to the Commercial Code. These new Principles are part of a forward-thinking movement to improve Japanese corporate policy and are the result of earnest and vigorous debate between the practical and academic sides of this topic.', 'The Committee revised the first version of the Principles by synthesizing these discussions, including the appointment of outside directors who are professors at national universities and certain revisions to the Commercial Code. These new Principles are part of a forward-thinking movement to improve Japanese corporate policy and are the result of earnest and vigorous debate between the practical and academic sides of this topic.', 'Japan', 'governance', 'in_force', '2001-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_21', ARRAY['guidance_frameworks', 'sdg9', 'sdg16', 'disclosure', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e1e48cd0-7cf4-5284-af08-7ff95650abc4', 'Japan Confirmation etc. of Release Amounts of Specific Chemical', 'Act on Confirmation etc. of Release Amounts of Specific Chemical Substances in the Environment and Promotion of Improvements to the Management Thereof', 'The purpose of this Act is to promote voluntary improvement of the management of chemical substances by business operators and to prevent any impediments to the preservation of the environment by taking measures for the confirmation of release amounts, etc. of specific chemical substances in the environment, measures for the provision of information concerning the properties and handling of specific chemical substances by business operators, and other relevant measures, while giving consideration to the trend for international cooperation on the management of chemical substances pertaining to the preservation of the environment, taking into account scientific knowledge on chemical substances and the condition of the manufacture, use, and other handling of chemical substances, and gaining the understanding of business operators and citizens.', 'The purpose of this Act is to promote voluntary improvement of the management of chemical substances by business operators and to prevent any impediments to the preservation of the environment by taking measures for the confirmation of release amounts, etc. of specific chemical substances in the environment, measures for the provision of information concerning the properties and handling of specific chemical substances by business operators, and other relevant measures, while giving consideration to the trend for international cooperation on the management of chemical substances pertaining to the preservation of the environment, taking into account scientific knowledge on chemical substances and the condition of the manufacture, use, and other handling of chemical substances, and gaining the understanding of business operators and citizens.', 'The purpose of this Act is to promote voluntary improvement of the management of chemical substances by business operators and to prevent any impediments to the preservation of the environment by taking measures for the confirmation of release amounts, etc. of specific chemical substances in the environment, measures for the provision of information concerning the properties and handling of specific chemical substances by business operators, and other relevant measures, while giving consideration to the trend for international cooperation on the management of chemical substances pertaining to the preservation of the environment, taking into account scientific knowledge on chemical substances and the condition of the manufacture, use, and other handling of chemical substances, and gaining the understanding of business operators and citizens.', 'Japan', 'governance', 'in_force', '1999-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_30', ARRAY['other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'japan', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('97fef38f-fcd0-5e0d-9d8f-a4874929081c', 'Japan Rational Use of Energy (1979) and Act', 'Act concerning the Rational Use of Energy (1979) and Act on Promotion of Global Warming Countermeasures', 'The purpose of this Act is, with the aim of contributing to the assurance of the effective utilization of fuel resources according to the economic and social environment concerning energy both inside and outside Japan, to implement the measures required for the rational use of energy with regard to factories, transportation, buildings, and machinery and equipment as well as other necessary measures, etc. for comprehensively promoting the rational use of energy, thereby contributing to the sound development of the national economy.', 'The purpose of this Act is, with the aim of contributing to the assurance of the effective utilization of fuel resources according to the economic and social environment concerning energy both inside and outside Japan, to implement the measures required for the rational use of energy with regard to factories, transportation, buildings, and machinery and equipment as well as other necessary measures, etc. for comprehensively promoting the rational use of energy, thereby contributing to the sound development of the national economy.', 'The purpose of this Act is, with the aim of contributing to the assurance of the effective utilization of fuel resources according to the economic and social environment concerning energy both inside and outside Japan, to implement the measures required for the rational use of energy with regard to factories, transportation, buildings, and machinery and equipment as well as other necessary measures, etc. for comprehensively promoting the rational use of energy, thereby contributing to the sound development of the national economy.', 'Japan', 'climate', 'in_force', '1998-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_3', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'japan', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
